def align(panel, x):
    from scipy.optimize import least_squares
    (u, v) = (panel['u'], panel['v'])

    def f(a):
        return one(np.c_[a, pair(a), a ** 3])
    F = f(u)
    mask = np.max(abs(v - np.median(v, axis=0)), axis=1) < 6
    for _ in range(3):
        c = ls(F[mask], v[mask])
        r = np.linalg.norm(F @ c - v, axis=1)
        mask = r < max(7 * np.median(r), 0.001)
    c[abs(c) < 0.001] = 0
    return np.array([least_squares(lambda a: (f(a[None]) @ c)[0] - q, np.linalg.solve(c[1:5].T, q - c[0]), gtol=1e-11).x for q in x])
